```
FUNCTION_BLOCK FB
VAR_INPUT
    startBtn   : BOOL;
    abortBtn   : BOOL;
    setpoint   : REAL;
    pv         : REAL;
    maxDuration: INT;
END_VAR
VAR_OUTPUT
    elapsed  : INT;
    phase    : INT;
    timeout  : BOOL;
END_VAR
VAR
    prevStartBtn : BOOL := FALSE;
    prevPhase    : INT  := 0;
    prevElapsed  : INT  := 0;
    prevTimeout  : BOOL := FALSE;
END_VAR

// Detect rising edge of start button
VAR
    risingStart : BOOL;
END_VAR
risingStart := startBtn AND NOT prevStartBtn;

// Abort has highest priority
IF abortBtn THEN
    phase   := 9;
    elapsed := prevElapsed;
    timeout := prevTimeout;
    // risingStart in this scan is ignored
ELSE
    // New batch start on rising edge of start button
    IF risingStart THEN
        phase   := 1;
        elapsed := 0;
        timeout := FALSE;
    ELSE
        // No abort, no new start: update based on previous state
        IF (prevPhase = 1) OR (prevPhase = 2) THEN
            // Running phase: increment scan counter
            elapsed := prevElapsed + 1;

            // Check for timeout
            IF elapsed >= maxDuration THEN
                timeout := TRUE;
                phase   := 3;                // completed due to timeout
            ELSE
                // No timeout: decide heating/holding according to temperature
                IF prevPhase = 1 THEN
                    IF pv >= setpoint THEN
                        phase := 2;          // temperature reached, go to holding
                    ELSE
                        phase := 1;          // still heating
                    END_IF;
                ELSE // prevPhase = 2
                    phase := 2;              // remain in holding
                END_IF;
                timeout := prevTimeout;       // should be FALSE
            END_IF;
        ELSE
            // Previous scan was not a running phase: keep state unchanged
            phase   := prevPhase;
            elapsed := prevElapsed;
            timeout := prevTimeout;
        END_IF;
    END_IF;
END_IF;

// Update memory for next scan
prevStartBtn := startBtn;
prevPhase    := phase;
prevElapsed  := elapsed;
prevTimeout  := timeout;

END_FUNCTION_BLOCK
```

